Per_Exec_Wake led_execute( void )
{
	static UInt8 count = LED_BASE_TIME/10;
	static UInt8 fifo_state = FALSE;
    
    if((--count)==0)
    {
        fifo_state = out_fifo_exec( NULL , led_fifo ) ;     			

        count = LED_BASE_TIME/10;
    }
		
		if( fifo_state )
			return PER_EXEC_SLEEP;
		else
			return PER_EXEC_WAKE;
}


